import * as React from "react";
import * as Axios from 'axios';
import axios from 'axios';
import { strict as assert } from 'assert';
const atm_isp_pb = require('./atm_isp_pb');

const DEFAULT_SVR = 'localhost'
const DEFAULT_PORT = ':8080'
const ENDPTS = {
    app_client_closing: '/app/client-closing',
    app_platforms: '/nvds/platforms',
    burn_otp: '/nvds/otp/rmw',
    load_nvds: '/nvds/flash',
    load_flash: '/elf',
    verify_flash: '/verify_flash',
};

function mkBaseURL(svr: string, port: string) {
  return `http://${svr}${port}`;
}

function mkAxiosCfg(svr: string, port: string) {
  return {
    baseURL: mkBaseURL(svr, port),
    headers: {
      "content-type": "multipart/form-data"
    }
  };
}

enum BinTy {
    NvdsOTP = 1 << 1,
    NvdsFlash = 1 << 2,
    Firmware = 1 << 3,
}

enum AtmArchive {
    Arch =
	BinTy.NvdsOTP |
	BinTy.NvdsFlash |
	BinTy.Firmware
}

const BinTypes = [
    BinTy.NvdsOTP,
    BinTy.NvdsFlash,
    BinTy.Firmware,
];

enum BinExts {
    nvm = BinTy.NvdsOTP,
    bin = BinTy.NvdsFlash,
    elf = BinTy.Firmware,
    atm = AtmArchive.Arch,
}

enum BinDescrs {
    'OTP' = BinTy.NvdsOTP,
    'Flash NVDS' = BinTy.NvdsFlash,
    'Firmware' = BinTy.Firmware,
    'Atmosic Archive' = AtmArchive.Arch,
}

interface BlobXargs {
    blob: Blob,
    xargs: XargTy,
    checked: boolean,
}

type BinMap = Map<BinTy, BlobXargs>;

type XargTy = Array<string>;

interface BinHttpSvc {
    post(endpt: string, image: Blob, xargs: XargTy): Promise<Uint8Array>;
    get(endpt: string, xargs: XargTy): Promise<Uint8Array>;
}

class atm2x_http implements BinHttpSvc {
    constructor(private config: Axios.AxiosRequestConfig) {
    }
    request(req: Axios.Method, endpt: string, image: Blob | undefined, xargs: XargTy): Promise<Uint8Array> {
	let uri = endpt;
	if (xargs.length > 0) {
	    uri += '?xargs=' + encodeURIComponent(xargs.join(' '));
	}
	console.log('uri:', uri);
	let config = this.config;
        config["headers"] = {
	    "content-type": "text/plain"
        };
	config["responseType"] = "blob";
	let axios_req = (): Promise<Axios.AxiosResponse<any>> => {
	    switch(req) {
		case 'get':
		case 'GET':
		    console.log(req, endpt, xargs);
		    return axios.get(uri, config);
		case 'post':
		case 'POST':
		    if (process.env.NODE_ENV !== 'production') {
			assert(image !== undefined);
			console.log(req, endpt, image.size, xargs);
		    }
		    return axios.post(uri, image, config);
		default:
		    throw new Error(`Unhandled HTTP method '${req}'`);
	    }
	}
	return new Promise<any>((res, rej) => {
	    axios_req()
		.then(function(response: any) {
		    setTimeout(() => {
			rej(new Error('timeout in atm2x_http ' + req));
		    }, 500);
		    console.log(
			`Response status: ${response.status} (${response.statusText})`
		    );
		    if (response.status === 200) {
			var myReader = new FileReader();
			myReader.onload = function() {
			    res(new Uint8Array(myReader.result as ArrayBuffer));
			};
			myReader.readAsArrayBuffer(response.data);
		    } else if (response.status === 206) {
			rej(new Error('OpenOCD BinHttpSvc err: ' + response.statusText));
		    } else {
			rej(new Error(`Unknown status: ${response.status} - ${response.statusText}`));
		    }
		})
		.catch(rej);
	});
    }
    post(endpt: string, image: Blob, xargs: XargTy): Promise<Uint8Array> {
	return this.request('post', endpt, image, xargs);
    }
    get(endpt: string, xargs: XargTy): Promise<Uint8Array> {
	return this.request('get', endpt, undefined, xargs);
    }
}

interface ISPState {
    binaries: BinMap;
    axios_config: Axios.AxiosRequestConfig;
    intervalId: number;
    platforms: string[];
}

class BXargs implements BlobXargs {
    constructor(public blob: Blob, public xargs: XargTy, public checked: boolean = true) {
    }
}

type BinCallbkTy = (blob: Blob, xargs: XargTy) => Promise<void>;

interface BinHandler {
    handleNvdsOTP: BinCallbkTy;
    handleNvdsFlash: BinCallbkTy;
    handleFirmware: BinCallbkTy;
}

class PushBin implements BinHandler {
    constructor(private http: BinHttpSvc) {
    }
    handleNvdsOTP = (blob: Blob, xargs: XargTy): Promise<void> => {
	return new Promise<void>((res) => {
	    // Ignore unused resp_data (_resp_data should have worked but wouldn't...)
	    // @ts-ignore
	    this.http.post(ENDPTS.burn_otp, blob, xargs).then((resp_data: Uint8Array) => res());
	});
    }
    handleNvdsFlash = (blob: Blob, xargs: XargTy): Promise<void> => {
	return new Promise<void>((res) => {
	    // Ignore unused resp_data (_resp_data should have worked but wouldn't...)
	    // @ts-ignore
	    this.http.post(ENDPTS.load_nvds, blob, xargs).then((resp_data: Uint8Array) => res());
	});
    }
    handleFirmware = (blob: Blob, xargs: XargTy): Promise<void> => {
	return new Promise<void>((res) => {
	    // @ts-ignore
	    this.http.post(ENDPTS.load_flash, blob, xargs, (dummy: any) => {
		this.http.post(ENDPTS.verify_flash, blob, xargs);
		// Ignore unused resp_data (_resp_data should have worked but wouldn't...)
		// @ts-ignore
	    }).then((resp_data: Uint8Array) => res());
	});
    }
}

function readBlobAsArrayBuf(blob: Blob): Promise<ArrayBuffer> {
    return new Promise<ArrayBuffer>((resolve, reject) => {
	var reader = new FileReader();
	reader.onload = () => {
	    if (reader.result instanceof ArrayBuffer) {
		resolve(reader.result);
	    } else {
		reject(new Error('Blob result was not an array buffer'));
	    }
	}
	reader.readAsArrayBuffer(blob);
    });
}

function cmdUnionCase2BinTy(cmdUnionCase: number): BinTy {
    switch (cmdUnionCase) {
	case atm_isp_pb.Archive.Command.CmdunionCase.CMDUNION_NOT_SET:
	    throw new Error('Got a CMDUNION_NOT_SET');
	case atm_isp_pb.Archive.Command.CmdunionCase.NVDSREADMODWRITE:
	    throw new Error('Got an NVDSREADMODWRITE');
	case atm_isp_pb.Archive.Command.CmdunionCase.LOADFLASH:
	    return BinTy.Firmware;
	case atm_isp_pb.Archive.Command.CmdunionCase.LOADFLASHNVDS:
	    return BinTy.NvdsFlash;
	case atm_isp_pb.Archive.Command.CmdunionCase.LOADOTPNVDS:
	    return BinTy.NvdsOTP;
	default:
	    throw new Error('Unknown case: ' + cmdUnionCase);
    }
}

export class ISP extends React.Component<{}, ISPState> {
    constructor(props: object) {
	super(props);
	this.state = {
	    binaries: new Map<BinTy, BlobXargs>(),
	    axios_config: mkAxiosCfg(DEFAULT_SVR, DEFAULT_PORT),
	    intervalId: 0,
	    platforms: [],
	};
    }
    getArch = (e: React.ChangeEvent<HTMLInputElement>, arch: AtmArchive) => {
	if (e.target.files) {
	    let setBinaries = async (blob: Blob) => {
		if (arch !== AtmArchive.Arch) {
		    console.error('Unknown ATM archive type', arch);
		    return
		}
		let buf = await readBlobAsArrayBuf(blob);
		let decoded_arch = atm_isp_pb.Archive.deserializeBinary(buf)
		if (decoded_arch.getMeta() === undefined) {
		    let platforms_str = this.state.platforms.join(', ');
		    alert(`No platform information exists in the uploaded archive file.  Proceed to push if the archive is indeed for "${platforms_str}."`);
		} else {
		    let platform_name = decoded_arch.getMeta().getPlatform().getName()
		    console.log('platform name:', platform_name)
		    if (this.state.platforms.find(p => p === platform_name) === undefined) {
			alert(`Platform mismatch: the uploaded archive file is for platform ${platform_name}, but expected ` + this.state.platforms.join(", "));
			return
		    }
		}
		decoded_arch.getScriptList()
		    .forEach((cmdUnion: any) => {
			let binTy = cmdUnionCase2BinTy(cmdUnion.getCmdunionCase());
			var commonLoad;
			var xargs_rev: XargTy = [];
			let xargs_add = (intArg: number) => {
			    if (intArg === 0 && xargs_rev.length === 0) {
				// Due to the design of the protobuf format,
				// there's currently no way to distinguish
				// between 0 and an undefined argument for a Tcl
				// command.  (The archive should either be
				// changed such that a command's arguments are
				// simply a list of strings, which is
				// undesirable, or have to have a way to mark an
				// argument undefined rather than take 0 to mean
				// undefined.)  For now, since neither
				// sydney_load_flash_nvds nor sydney_load_flash
				// have an argument list ending in an optional
				// one, we use this xargs_rev hack to preserve 0
				// in the middle arguments...
				return;
			    }
			    xargs_rev.push(Number(intArg).toString());
			}
			switch (binTy) {
			    case BinTy.NvdsOTP:
				commonLoad = cmdUnion.getLoadotpnvds().getCommonload();
				break;
			    case BinTy.NvdsFlash:
				let cmn = cmdUnion.getLoadflashnvds().getCommonloadflash();
				commonLoad = cmn.getCommonload();
				xargs_add(cmn.getRegionSize());
				xargs_add(cmn.getRegionStart());
				break;
			    case BinTy.Firmware: {
				let cmn = cmdUnion.getLoadflash().getCommonloadflash();
				commonLoad = cmn.getCommonload();
				xargs_add(cmdUnion.getLoadflash().getAddress());
				xargs_add(cmn.getRegionSize());
				xargs_add(cmn.getRegionStart());
				break;
			    }
			}
			let blob = new Blob([commonLoad.getImage_asU8()]);
			this.setState((prevState) => {
			    let newState = prevState;
			    newState.binaries.set(binTy, new BXargs(blob, xargs_rev.reverse()));
			    return newState;
			});
		    });
	    }
	    setBinaries(e.target.files[0]);
	} else {
	    console.log('No archive found in file upload');
	}
    }
    static eleId(bin: BinTy | AtmArchive): string {
	return 'bininput' + BinExts[bin];
    }
    itrBins = (bh: BinHandler): Promise<void> => {
	return new Promise<void>(async (resolve, reject) => {
	    var err: Error | undefined = undefined;
	    let set_err = (e: Error) => {
		err = e;
	    }
	    for (var [bin, bxargs] of this.state.binaries) {
		if (!bxargs.checked) {
		    continue;
		}
		let blob = bxargs.blob;
		let xargs = bxargs.xargs;
		switch (bin) {
		    case BinTy.NvdsOTP:
			await bh.handleNvdsOTP(blob, xargs).catch(set_err);
			break;
		    case BinTy.NvdsFlash:
			await bh.handleNvdsFlash(blob, xargs).catch(set_err);
			break;
		    case BinTy.Firmware:
			await bh.handleFirmware(blob, xargs).catch(set_err);
			break;
		    default:
			err = new Error('Unhandled bin case: ' + bin + ' ' + blob.size);
			break;
		}
		if (err) {
		    break;
		}
	    }
	    if (err) {
		return reject(err);
	    } else {
		return resolve();
	    }
	});
    }
    push = () => {
	try {
	    this.itrBins(new PushBin(new atm2x_http(this.state.axios_config)))
		.then( () => alert('Push successful.'))
		.catch((err) => alert('Failed to push: ' + err));
	} catch (e) {
	    alert(e);
	}
    }
    renderBinOrArchFile = (bin: BinTy | AtmArchive, onChg: (e: React.ChangeEvent<HTMLInputElement>) => void) => {
	let eleId = ISP.eleId(bin);
	return (<div key={eleId}><label htmlFor={eleId}>{BinDescrs[bin]}: </label><input type="file" name={eleId} id={eleId} onChange={onChg} accept={`.${BinExts[bin]}`}></input></div>);
    }
    renderBinFile = (bin: BinTy) => {
	let eleId = ISP.eleId(bin);
	return (
		<div key={eleId}>
		<label htmlFor={eleId}>
		<input type="checkbox"
	    checked={this.state.binaries.has(bin) && (this.state.binaries.get(bin)!).checked}
	    disabled={!this.state.binaries.has(bin)}
	    onChange={(e: React.ChangeEvent<HTMLInputElement>) => {
		let checked = e.target.checked;
		this.setState((prev) => {
		    let next = prev;
		    const bxargs = next.binaries.get(bin);
		    if (!bxargs) {
			throw new Error(`Expected an entry for ${bin} in binaries map`);
		    }
		    bxargs.checked = checked;
		    next.binaries.set(bin, bxargs);
		    return next;
		})}}
		/>
		<span>{BinDescrs[bin]}</span>
		</label>
		</div>
	);
    }
    renderArchFile = (arch: AtmArchive) => {
	return this.renderBinOrArchFile(arch, (e: React.ChangeEvent<HTMLInputElement>) => {
	    this.getArch(e, arch);
	});
    }
    render_dev_eles() {
	if (process.env.NODE_ENV === 'production') {
	    return [];
	}
	return [
		<br></br>,
		<br></br>,
		<label htmlFor={'svr'}>
		<span>Server IP and port: </span>
		<input
		    type="text" id="svr"
		    value={this.state.axios_config.baseURL}
		    onChange={(e: React.ChangeEvent<HTMLInputElement>) => {
			let baseURL = e.target.value;
			this.setState((prev) => {
			    let next = prev;
			    next.axios_config.baseURL = baseURL;
			    return next;
			})}}
		/>
		</label>
	];
    }

    closeWindow = () => {
	window.opener = null;
	window.open("", "_self");
	window.close();
    };

    watchDog = () => {
	let app = this;
	let bininputatm = document.getElementById('bininputatm') as HTMLInputElement;
	axios
	    .get(ENDPTS.app_platforms, {
		baseURL: app.state.axios_config.baseURL,
		headers: {
		    "content-type": "text/plain"
		}
	    })
	    .then((response) => {
		if (app.isConnected()) {
		    return;
		}
		console.log("Going up", response.data);
		app.setState({platforms: response.data.split(',')});
		if (bininputatm !== null) {
		    bininputatm.disabled = false
		}
	    })
	    .catch(function(error) {
		if (!app.isConnected()) {
		    return;
		}
		console.log("Going down: ", error);
		if (bininputatm !== null) {
		    bininputatm.disabled = true
		}
		app.setState({platforms: []});
		alert('ISP Tool shut down. You may close this window');
	    });
    }

    shutdown = () => {
	let url = this.state.axios_config.baseURL + ENDPTS.app_client_closing;
	axios
	    .post(url, 'dummy')
	    .then(this.closeWindow)
	    .catch((e) => alert(`Error occurred in closing the backend server: ${e}`));
    }
    render_app_eles() {
	return [
		<br></br>,
		<br></br>,
		<button type="button" onClick={this.shutdown}>Shutdown</button>,
	];
    }
    async componentDidMount() {
	this.setState(
            {},
            () => {
		var intervalId: number = window.setInterval(this.watchDog, 5 * 1000);
		// store intervalId in the state so it can be accessed later:
		this.setState({ intervalId: intervalId });
            }
	);
    }

    componentWillUnmount() {
	clearInterval(this.state.intervalId);
    }

    isConnected = () => {
	return this.state.platforms.length !== 0;
    }

    render() {
	let elements = [
	    [AtmArchive.Arch].map(this.renderArchFile),
		<br></br>,
	    BinTypes.map(this.renderBinFile),
		<br></br>,
		<button type="button" onClick={this.push}>Push</button>,
		<br></br>,
	].concat(this.render_dev_eles()).concat(this.render_app_eles()).concat([
		<br></br>,
		<div>
		<span>
		Status: {this.isConnected() ? "Connected" : "Disconnected"}
                </span>
		<div>
		</div>
		<span>
		Platform: {this.state.platforms.join(', ')}
                </span>
		</div>,
	]);
	if (!this.isConnected()) {
	    let bininputatm = document.getElementById('bininputatm') as HTMLInputElement;
	    if (bininputatm !== null) {
		bininputatm.disabled = true;
	    }
	}
	return elements;
    }
}
